import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Warum verbindet sich mein Gerät nicht oder bricht ab?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/04.fehlerbehebung/03.verbindung.md"},"headers":[],"relativePath":"de/adapter/esphome/fehlerbehebung/verbindung.md","filePath":"de/adapter/esphome/fehlerbehebung/verbindung.md","lastUpdated":1795571670000}'),a={name:"de/adapter/esphome/fehlerbehebung/verbindung.md"};function d(s,e,o,c,h,l){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="warum-verbindet-sich-mein-gerat-nicht-oder-bricht-ab" tabindex="-1">Warum verbindet sich mein Gerät nicht oder bricht ab? <a class="header-anchor" href="#warum-verbindet-sich-mein-gerat-nicht-oder-bricht-ab" aria-label="Permalink to &quot;Warum verbindet sich mein Gerät nicht oder bricht ab?&quot;">​</a></h1><p><a id="devices-offline-reporting-incorrect-password"></a></p><h2 id="warum-sind-nach-neustart-oder-update-alle-gerate-offline-oder-melden-incorrect-password" tabindex="-1">Warum sind nach Neustart oder Update alle Geräte offline oder melden &quot;incorrect password&quot;? <a class="header-anchor" href="#warum-sind-nach-neustart-oder-update-alle-gerate-offline-oder-melden-incorrect-password" aria-label="Permalink to &quot;Warum sind nach Neustart oder Update alle Geräte offline oder melden &quot;incorrect password&quot;?&quot;">​</a></h2><p>Beim Start setzt der Adapter <code>info._online</code> aller Geräte auf <code>false</code>. Dann liest er Adresse und Zugangsdaten aus den Geräteobjekten und verbindet sich mit jedem Gerät neu. Die Erkennung braucht er dafür nicht. Bis jedes Gerät geantwortet hat, sind manche noch offline.</p><p>Bleibt ein Gerät offline, sieh im Reiter „Geräte“ oder in <code>info._connectionStatus</code> nach:</p><table tabindex="0"><thead><tr><th>Status</th><th>Ursache</th><th>Abhilfe</th></tr></thead><tbody><tr><td><code>API password incorrect</code></td><td>Das Gerät nimmt das Passwort nicht mehr an, z. B. seit ESPHome 2026.1</td><td>„Verbindungseinstellungen ändern“, Schlüssel eintragen</td></tr><tr><td><code>Encryption Key Missing</code></td><td>Das Gerät nutzt jetzt einen Schlüssel</td><td>dasselbe</td></tr><tr><td><code>unreachable</code></td><td>Gerät aus oder unter anderer Adresse</td><td>Gerät und Adresse prüfen</td></tr></tbody></table><p>Hat sich die Adresse geändert, lösch das Gerät im Reiter „Geräte“ und füg es unter der neuen Adresse hinzu. Eine feste Adresse im Router verhindert das.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erstes-geraet#api-password-still-work-esphome">API-Passwort und ESPHome 2026.1</a></p><p><a id="device-disconnect-every-few-seconds"></a></p><h2 id="warum-trennt-sich-mein-gerat-alle-paar-sekunden" tabindex="-1">Warum trennt sich mein Gerät alle paar Sekunden? <a class="header-anchor" href="#warum-trennt-sich-mein-gerat-alle-paar-sekunden" aria-label="Permalink to &quot;Warum trennt sich mein Gerät alle paar Sekunden?&quot;">​</a></h2><p>Der Adapter pingt jedes verbundene Gerät im Ping-Intervall an. Bleiben so viele Antworten aus, wie unter „Ping-Versuche bis offline“ steht, trennt er die Verbindung und baut sie neu auf. Mit dem Standard von einem Versuch reicht im schwachen WLAN ein einziger verlorener Ping. Im Log stehen dann wiederholt <code>Connection to device &lt;IP&gt; lost …</code> und <code>ESPHome client … disconnected</code>.</p><ol><li>Setz in den Haupteinstellungen unter „Verbindungsverhalten für bekannte Geräte“ „Ping-Versuche bis offline“ auf <code>3</code>.</li><li>Prüf das WLAN-Signal des Geräts, z. B. mit einem <code>wifi_signal</code>-Sensor.</li><li>Hilft das nicht, setz in der YAML <code>power_save_mode: none</code> unter <code>wifi:</code> und flashe neu.</li></ol><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#reconnect-settings-exist-happens-device">Verbindungseinstellungen</a></p><p><a id="device-initialisation-needed-object-tree"></a></p><h2 id="warum-gibt-es-ein-gerat-initialisation-needed-im-objektbaum" tabindex="-1">Warum gibt es ein Gerät &quot;Initialisation needed&quot; im Objektbaum? <a class="header-anchor" href="#warum-gibt-es-ein-gerat-initialisation-needed-im-objektbaum" aria-label="Permalink to &quot;Warum gibt es ein Gerät &quot;Initialisation needed&quot; im Objektbaum?&quot;">​</a></h2><p>„Initialisation needed“ ist der Platzhaltername eines Geräts, das du hinzugefügt hast, das aber nie geantwortet hat. Den echten Namen kennt der Adapter erst nach der ersten Verbindung. Bis dahin schreibt er den Status des Versuchs unter <code>esphome.0.Initialisation needed.info</code>.</p><ol><li>Prüf im Reiter „Geräte“ Adresse und Schlüssel. Das Gerät steht dort unter seiner Adresse.</li><li>Lösch den Eintrag und füg das Gerät mit den richtigen Angaben neu hinzu.</li><li>Steht der Ordner „Initialisation needed“ danach noch im Tab „Objekte“, lösch ihn dort.</li></ol><p>Nach einem Neustart der Instanz versucht der Adapter ein solches Gerät nicht mehr, weil er es nie als Gerät gespeichert hat.</p>',18)])])}const b=t(a,[["render",d]]);export{m as __pageData,b as default};
